			// write pointer 2
			size = (int)Mem.ToManaged<UnsignedInt8, TP2>(value.Pointer2, temp.AsAux());
			writer.WriteBase64String(nameof(Repr.Data2), new(temp, 0, size));
				
			// write pointer 3
			size = (int)Mem.ToManaged<UnsignedInt8, TP3>(value.Pointer3, temp.AsAux());
