	/// <summary>
	/// Statically create a new <see cref="MixedStorage{T, TP1, TP2, TP3, TP4, TP5, TP6, TP7, TP8}"/> of given lengths.
	/// </summary>
	/// <param name="length1">The length in <typeparamref name="T"/> of the first location</param>
